from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Solid rows and columns are the panel dividers.
    divider_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    divider_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    divider_color = (
        grid[divider_rows[0]][0] if divider_rows
        else grid[0][divider_cols[0]]
    )
    row_edges = [-1] + divider_rows + [h]
    col_edges = [-1] + divider_cols + [w]

    panels = []
    for ri in range(len(row_edges) - 1):
        r0, r1 = row_edges[ri] + 1, row_edges[ri + 1]
        for ci in range(len(col_edges) - 1):
            c0, c1 = col_edges[ci] + 1, col_edges[ci + 1]
            panels.append((r0, r1, c0, c1))

    # The most frequent non-divider color is the panel background.
    counts = Counter(
        grid[r][c]
        for r in range(h) for c in range(w)
        if r not in divider_rows and c not in divider_cols
        and grid[r][c] != divider_color
    )
    background = counts.most_common(1)[0][0]

    def panel_score(p):
        r0, r1, c0, c1 = p
        return sum(
            grid[r][c] != background
            for r in range(r0, r1) for c in range(c0, c1)
        )

    source = max(panels, key=panel_score)
    r0, r1, c0, c1 = source
    template = [grid[r][c0:c1] for r in range(r0, r1)]

    out = [row[:] for row in grid]
    for a, b, x, y in panels:
        if (a, b, x, y) == source:
            continue
        for r in range(a, b):
            for c in range(x, y):
                out[r][c] = template[r - a][c - x]
    return out
